searchDatas1[8] = ['','Names Used for Buttons on a Scanner in This Help','./intro_buttonname.html', '	Names Used for Buttons on a Scanner in This Help	The following names are used for buttons on a scanner in this help. 	Buttons on a scanner	This is a general term for buttons on a scanner that can be set to perform a particular task using Button Event Manager.	The buttons on a scanner that can be set to perform a particular task using Button Event Manager vary depending on the scanner model.	Buttons on the connected scanner that can be set to perform a particular task are shown in "Select an event" in the 	[Button Settings] Window.	Scan button on a scanner	This is a general term for a button on a scanner which has the word "Scan" in the button name such as the [Scan/Enter] button or [Scan/Stop] button.	The name for the scan button on a scanner varies depending on the scanner model. For details, refer to the Operator\'s Guide of the scanner.'];
searchDatas1[9] = ['','Conditions on Licenses for the Open Source Software','./intro_oss.html', '	Conditions on Licenses for the Open Source Software	The open source software (OSS) is used in this manual.	The following shows the OSS names, versions, and license names, which are used in this manual.	No.	Name	Version	License Name	1	jquery.biggerlink.js	2.0.1	MIT license	2	jquery.cookie-1.4.1.min.js	1.4.1	MIT license	3	jquery.highlight-4.js	4	MIT license	4	jquery.url.js	1.1	Unlicense	5	jquery-3.7.1.min.js	3.7.1	MIT license'];
